begin;
alter table public.cms_entries drop constraint if exists cms_entries_entry_type_check;
alter table public.cms_entries add constraint cms_entries_entry_type_check check (entry_type in ('homepage','hero','solution','about','contact','developer','industry','footer','navigation','faq','testimonial','partner','client_logo','blog','legal','seo','dynamic_page','statistic'));
alter table public.cms_entries add column if not exists scheduled_at timestamptz, add column if not exists preview_token_hash text, add column if not exists seo jsonb not null default '{}', add column if not exists featured_image_id uuid references public.media_assets(id) on delete set null;
create table public.cms_categories (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.cms_tags (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, created_at timestamptz not null default now());
create table public.cms_entry_categories (entry_id uuid not null references public.cms_entries(id) on delete cascade, category_id uuid not null references public.cms_categories(id) on delete cascade, primary key(entry_id,category_id));
create table public.cms_entry_tags (entry_id uuid not null references public.cms_entries(id) on delete cascade, tag_id uuid not null references public.cms_tags(id) on delete cascade, primary key(entry_id,tag_id));
create table public.cms_related_entries (entry_id uuid not null references public.cms_entries(id) on delete cascade, related_entry_id uuid not null references public.cms_entries(id) on delete cascade, sort_order integer not null default 0, primary key(entry_id,related_entry_id), check(entry_id<>related_entry_id));
create table public.seo_redirects (id uuid primary key default gen_random_uuid(), source_path text not null unique, destination_path text not null, status_code integer not null default 308 check(status_code in (301,302,307,308)), is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.email_templates (id uuid primary key default gen_random_uuid(), key text not null unique, name text not null, subject text not null, html_body text not null, text_body text, variables text[] not null default '{}', status text not null default 'draft' check(status in ('draft','active','archived')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.notification_jobs (id uuid primary key default gen_random_uuid(), organisation_id uuid references public.organisations(id) on delete cascade, template_id uuid references public.email_templates(id), channel text not null check(channel in ('email','in_app','sms_placeholder','whatsapp_placeholder')), recipient text not null, priority text not null default 'normal' check(priority in ('low','normal','high','critical')), payload jsonb not null default '{}', status text not null default 'scheduled' check(status in ('scheduled','processing','sent','failed','cancelled')), scheduled_at timestamptz not null default now(), sent_at timestamptz, last_error text, attempts integer not null default 0, created_at timestamptz not null default now());
create table public.system_events (id uuid primary key default gen_random_uuid(), service text not null, severity text not null check(severity in ('info','warning','critical')), status text not null, message text not null, metadata jsonb not null default '{}', occurred_at timestamptz not null default now(), resolved_at timestamptz);
create table public.analytics_events (id uuid primary key default gen_random_uuid(), organisation_id uuid references public.organisations(id) on delete cascade, user_id uuid references public.profiles(id) on delete set null, event_name text not null, page_path text, feature_key text, metadata jsonb not null default '{}', occurred_at timestamptz not null default now());
create table public.integration_configs (id uuid primary key default gen_random_uuid(), organisation_id uuid references public.organisations(id) on delete cascade, provider text not null check(provider in ('upi_autopay','e_nach','bank','sms','whatsapp','email','google_analytics','google_tag_manager')), status text not null default 'placeholder' check(status in ('placeholder','configured','disabled')), public_config jsonb not null default '{}', secret_reference text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique nulls not distinct(organisation_id,provider));
create index cms_entries_schedule_idx on public.cms_entries(status,scheduled_at) where deleted_at is null;
create index notification_jobs_due_idx on public.notification_jobs(status,scheduled_at);
create index analytics_events_org_idx on public.analytics_events(organisation_id,occurred_at desc);
create index analytics_events_page_idx on public.analytics_events(page_path,occurred_at desc);
create index system_events_health_idx on public.system_events(severity,occurred_at desc) where resolved_at is null;
do $$ declare t text; begin foreach t in array array['cms_categories','cms_tags','cms_entry_categories','cms_entry_tags','cms_related_entries','seo_redirects','email_templates','notification_jobs','system_events','analytics_events','integration_configs'] loop execute format('alter table public.%I enable row level security',t); execute format('alter table public.%I force row level security',t); execute format('create policy %I on public.%I for all to authenticated using(public.is_super_admin()) with check(public.is_super_admin())',t||'_super_admin',t); end loop; end $$;
create policy analytics_tenant_read on public.analytics_events for select to authenticated using(organisation_id is not null and public.is_organisation_member(organisation_id));
create policy integrations_tenant_access on public.integration_configs for all to authenticated using(organisation_id is not null and public.is_organisation_member(organisation_id)) with check(organisation_id is not null and public.is_organisation_member(organisation_id));
insert into public.email_templates(key,name,subject,html_body,variables,status) values
('welcome','Welcome','Welcome to FirstPay','<h1>Welcome, {{name}}</h1>','{name,organisation}', 'active'),('invitation','Invitation','You are invited to FirstPay','<p>Join {{organisation}}: {{invite_url}}</p>','{organisation,invite_url}','active'),('password_reset','Password Reset','Reset your FirstPay password','<p>Reset securely: {{reset_url}}</p>','{reset_url}','active'),('lead_notification','Lead Notification','New lead: {{company}}','<p>{{company}} requested contact.</p>','{company,email}','active'),('demo_request','Demo Request','FirstPay demo request','<p>Demo request from {{name}}</p>','{name,email}','active'),('newsletter','Newsletter','FirstPay update','<p>{{content}}</p>','{content}','draft'),('support','Support','Support update {{ticket}}','<p>{{message}}</p>','{ticket,message}','active'),('announcement','Announcement','{{title}}','<p>{{body}}</p>','{title,body}','active'),('client_activation','Client Activation','Your FirstPay workspace is active','<p>{{organisation}} is active.</p>','{organisation}','active'),('suspension','Suspension','FirstPay workspace notice','<p>{{organisation}} has been suspended.</p>','{organisation,reason}','active') on conflict(key) do nothing;
commit;
